try{ 

var query ="select id from Agency_Info__c where Account__c=\'"+'{!Account.Id}'+"\' and Recordtype.Name=\'Distribution\' limit 1"; 

var query2 ="select id from Agency_Info__c where Account__c=\'"+'{!Account.Id}'+"\' and PCC__c!='' and Recordtype.Name=\'GDS\' limit 1"; 

var query3 ="select id from Agency_Info__c where Account__c in (select Primary_Account__c from Account_Relation__c where Related_Account__c=\'"+'{!Account.Id}'+"\' and Active__c=TRUE) and PCC__c!='' limit 1"; 

var query4 ="select id from Contract__c where Account__c=\'"+'{!Account.Id}'+"\' ";


var records = sforce.connection.query(query); 
var records2= sforce.connection.query(query2); 
var records3= sforce.connection.query(query3); 
var records4= sforce.connection.query(query4); 

var records1 = records.getArray('records'); 
var records21= records2.getArray('records'); 
var records31= records3.getArray('records'); 
var records41= records4.getArray('records'); 


window.location.href = '/apex/iDealEligibilityAccSearch?id={!Account.Id}&count='+records1.length+'&count2='+records21.length+'&count3='+records31.length+'&count4='+records41.length; 
} 
catch(err) { 
alert(err); 
} 
